package com.backand.tambayanguild.service;

import com.backand.tambayanguild.entity.*;
import com.backand.tambayanguild.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.LocalDate;
import java.util.*;

@Service
public class ProgressService {
 private final UserRepository users; private final GuildMembersRepository memberships; private final QuestRepository quests;
 private final UserQuestRepository userQuests; private final BadgeRepository badges;
 public ProgressService(UserRepository users,GuildMembersRepository memberships,QuestRepository quests,UserQuestRepository userQuests,BadgeRepository badges){this.users=users;this.memberships=memberships;this.quests=quests;this.userQuests=userQuests;this.badges=badges;}
 public UserEntity user(Long id){return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));}
 public GuildMembersEntity requireMember(Long guildId,Long userId){return memberships.findByGuild_IdAndUser_Id(guildId,userId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"You must be a guild member"));}
 public void requireSelf(Long actor,Long target){if(!Objects.equals(actor,target))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You may only act on your own account");}
 @Transactional public void recordStudyActivity(Long userId,int xp,int coins,String activityCode){UserEntity user=user(userId);user.setXp(user.getXp()+xp);user.setCoins(user.getCoins()+coins);LocalDate today=LocalDate.now();List<GuildMembersEntity> rows=memberships.findByUser_Id(userId);for(var m:rows){LocalDate last=m.getLastActiveDate();if(!today.equals(last)){m.setCurrentStreak(last!=null&&last.equals(today.minusDays(1))?m.getCurrentStreak()+1:1);m.setBestStreak(Math.max(m.getBestStreak(),m.getCurrentStreak()));m.setLastActiveDate(today);}}updateQuests(user,activityCode,1);awardMilestoneBadges(user);}
 public void recordStudyActivity(Long userId,int xp,int coins){recordStudyActivity(userId,xp,coins,"STUDY");}
 public void updateQuests(UserEntity user,String code,int count){LocalDate today=LocalDate.now();for(QuestEntity quest:quests.findByQuestDate(today)){if(!quest.getCode().equals(code))continue;UserQuestEntity progress=userQuests.findByUser_IdAndQuest_Id(user.getId(),quest.getId()).orElseGet(()->userQuests.save(new UserQuestEntity(user,quest)));if(progress.isCompleted())continue;progress.setProgressCount(Math.min(quest.getTargetCount(),progress.getProgressCount()+count));if(progress.getProgressCount()>=quest.getTargetCount()){progress.complete();user.setXp(user.getXp()+quest.getRewardXp());user.setCoins(user.getCoins()+quest.getRewardCoins());}}}
 public void awardMilestoneBadges(UserEntity user){award(user,"FIRST_STUDY","First Steps","Complete your first study activity",user.getXp()>=10);award(user,"XP_500","Scholar","Earn 500 XP",user.getXp()>=500);award(user,"STREAK_7","One Week Strong","Reach a 7 day guild streak",memberships.findByUser_Id(user.getId()).stream().anyMatch(m->m.getBestStreak()>=7));}
 private void award(UserEntity user,String code,String name,String description,boolean earned){if(earned&&!badges.existsByUser_IdAndCode(user.getId(),code))badges.save(new BadgeEntity(user,code,name,description));}
 @Transactional public List<QuestEntity> today(){LocalDate today=LocalDate.now();if(quests.findByQuestDate(today).isEmpty()){for(String[] spec:new String[][]{{"STUDY","Study for 10 minutes","Complete any study activity","20","10"},{"QUIZ","Quiz yourself","Complete a quiz session","30","15"},{"CARDS","Review flashcards","Review a shared flashcard deck","15","8"}})if(quests.findByQuestDateAndCode(today,spec[0]).isEmpty())quests.save(new QuestEntity(spec[0],spec[1],spec[2],1,Integer.parseInt(spec[3]),Integer.parseInt(spec[4]),today));}else{for(String[] spec:new String[][]{{"STUDY","Study for 10 minutes","Complete any study activity","20","10"},{"QUIZ","Quiz yourself","Complete a quiz session","30","15"},{"CARDS","Review flashcards","Review a shared flashcard deck","15","8"}})if(quests.findByQuestDateAndCode(today,spec[0]).isEmpty())quests.save(new QuestEntity(spec[0],spec[1],spec[2],1,Integer.parseInt(spec[3]),Integer.parseInt(spec[4]),today));}return quests.findByQuestDate(today);}
 public List<Map<String,Object>> questProgress(Long userId){user(userId);return today().stream().map(q->{var p=userQuests.findByUser_IdAndQuest_Id(userId,q.getId()).orElse(null);Map<String,Object> m=new LinkedHashMap<>();Map<String,Object> detail=new LinkedHashMap<>();detail.put("id",q.getId());detail.put("code",q.getCode());detail.put("name",q.getName());detail.put("description",q.getDescription());detail.put("targetCount",q.getTargetCount());detail.put("rewardXp",q.getRewardXp());detail.put("rewardCoins",q.getRewardCoins());m.put("quest",detail);m.put("progress",p==null?0:p.getProgressCount());m.put("completed",p!=null&&p.isCompleted());return m;}).toList();}
 public List<Map<String,Object>> badges(Long userId){user(userId);return badges.findByUser_IdOrderByEarnedAtDesc(userId).stream().map(b->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",b.getId());m.put("code",b.getCode());m.put("name",b.getName());m.put("description",b.getDescription());m.put("earnedAt",b.getEarnedAt());return m;}).toList();}
 public Map<String,Object> dashboard(Long userId){UserEntity u=user(userId);List<GuildMembersEntity> gs=memberships.findByUser_Id(userId);int streak=gs.stream().mapToInt(GuildMembersEntity::getCurrentStreak).max().orElse(0);Map<String,Object> m=new LinkedHashMap<>();m.put("userId",u.getId());m.put("xp",u.getXp());m.put("level",u.getXp()/500+1);m.put("coins",u.getCoins());m.put("currentStreak",streak);m.put("bestStreak",gs.stream().mapToInt(GuildMembersEntity::getBestStreak).max().orElse(0));m.put("badges",badges(userId));m.put("quests",questProgress(userId));return m;}
 public List<Map<String,Object>> leaderboard(List<UserEntity> users){return users.stream().limit(100).map(u->{Map<String,Object> m=new LinkedHashMap<>();m.put("userId",u.getId());m.put("username",u.getUsername());m.put("xp",u.getXp());m.put("level",u.getXp()/500+1);m.put("avatarUrl",u.getAvatarUrl());return m;}).toList();}
}
